    private void createKeystore(boolean crls) throws Exception {
        this.serverCA = new TestCA(CertificateCreationOptions.builder(new X500Name("cn=Server CA, dc=test")).build());
        this.clientCA = new TestCA(CertificateCreationOptions.builder(new X500Name("cn=Client CA, dc=test")).build());
        KeyPair serverKey = TestCA.generateKeyPair();
        X509Certificate serverCertificate = this.serverCA.createAndSignCertificate(
                CertificateCreationOptions.builder(new X500Name("cn=localhost, dc=test")).build(), serverKey);
        KeyPair clientKey = TestCA.generateKeyPair();
        this.clientCertificate = this.clientCA.createAndSignCertificate(
                CertificateCreationOptions.builder(new X500Name("cn=admin, dc=test")).build(), clientKey);
        this.clientKeys = KeyStore.getInstance("PKCS12");
        this.clientKeys.load(null, null);
        this.clientKeys.setKeyEntry("client", clientKey.getPrivate(), "test-password".toCharArray(),
                new Certificate[] { this.clientCertificate, this.clientCA.getCertificate() });
        KeyStore serverKeys = KeyStore.getInstance("PKCS12");
        serverKeys.load(null, null);
        serverKeys.setKeyEntry("server", serverKey.getPrivate(), "test-password".toCharArray(),
                new Certificate[] { serverCertificate, this.serverCA.getCertificate() });
        serverKeys.setCertificateEntry("client-ca", this.clientCA.getCertificate());
        Path file = this.directory.resolve("server.p12");
        try (var out = Files.newOutputStream(file)) { serverKeys.store(out, "test-password".toCharArray()); }
        CryptoService crypto = mock(CryptoService.class);
        when(crypto.decryptAes(any(char[].class))).thenAnswer(call -> call.getArgument(0));
        when(crypto.encryptAes(any(char[].class))).thenAnswer(call -> call.getArgument(0));
        EventAdmin eventAdmin = mock(EventAdmin.class);
        doAnswer(call -> {
            Event event = call.getArgument(0);
            if (this.active) {
                invoke("handleEvent", Event.class, event);
                this.events.offer(event);
            }
            return null;
        }).when(eventAdmin).postEvent(any());
        ComponentContext context = mock(ComponentContext.class);
        when(context.getBundleContext()).thenReturn(this.framework.getBundleContext());
        this.keystore = new FilesystemKeystoreServiceImpl();
        this.keystore.setCryptoService(crypto);
        this.keystore.setEventAdmin(eventAdmin);
        Map<String, Object> options = new HashMap<>(Map.of("kura.service.pid", "test-keystore", "keystore.path",
                file.toString(), "keystore.password", "test-password", "randomize.password", false,
                "crl.management.enabled", crls));
        if (crls) {
            this.crlServer = new TestServer(0, Optional.empty());
            publishCRL();
            options.put("crl.urls", new String[] { "http://127.0.0.1:" + this.crlServer.getPort() + "/crl.pem" });
            options.put("crl.check.interval", 1L);
            options.put("crl.check.interval.time.unit", TimeUnit.SECONDS.name());
            options.put("crl.update.interval", 1L);
            options.put("crl.update.interval.time.unit", TimeUnit.SECONDS.name());
        }
        this.keystore.activate(context, options);
        this.manager.getClass().getMethod("setKeystoreService", KeystoreService.class, Map.class)
                .invoke(this.manager, this.keystore, Map.of("kura.service.pid", "test-keystore"));
    }

    private void publishCRL() throws Exception {
        try (ByteArrayOutputStream out = new ByteArrayOutputStream()) {
            TestCA.encodeToPEM(this.clientCA.generateCRL(CRLCreationOptions.builder().build()), out);
            this.crlServer.setResource("/crl.pem", out.toByteArray());
        }
    }

    private SSLContext clientContext(boolean clientAuth) throws Exception {
        KeyStore trust = KeyStore.getInstance("PKCS12");
        trust.load(null, null);
        trust.setCertificateEntry("server-ca", this.serverCA.getCertificate());
        TrustManagerFactory tmf = TrustManagerFactory.getInstance("PKIX");
        tmf.init(trust);
        KeyManagerFactory kmf = KeyManagerFactory.getInstance("SunX509");
        kmf.init(this.clientKeys, "test-password".toCharArray());
        SSLContext ssl = SSLContext.getInstance("TLS");
        ssl.init(clientAuth ? kmf.getKeyManagers() : null, tmf.getTrustManagers(), null);
        return ssl;
    }

    private void assertTlsHandshakeRejected(ServerConnector connector, boolean clientAuth) throws Exception {
        assertTrue(server().isStarted());
        assertTrue(connector.isOpen(), "A closed listener must not look like certificate rejection");
        CompletableFuture<Throwable> serverFailure = new CompletableFuture<>();
        SslHandshakeListener listener = new SslHandshakeListener() {
            @Override public void handshakeFailed(SslHandshakeListener.Event event, Throwable failure) {
                serverFailure.complete(failure);
            }
        };
        connector.addBean(listener);
        try {
            // Depending on TLS alert delivery, the client sees an SSLException or a connection reset.
            assertThrows(IOException.class, () -> request(connector, true, clientAuth));
            assertInstanceOf(SSLException.class, serverFailure.get(3, TimeUnit.SECONDS),
                    "The running server must report an actual TLS handshake failure");
        } finally { connector.removeBean(listener); }
    }

    private int request(ServerConnector connector, boolean tls, boolean clientAuth) throws Exception {
        URL url = URI.create((tls ? "https" : "http") + "://127.0.0.1:" + connector.getLocalPort() + "/").toURL();
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setConnectTimeout(3000);
        connection.setReadTimeout(3000);
        connection.setInstanceFollowRedirects(false);
        connection.setRequestProperty("Connection", "close");
        try {
            if (tls) {
                SSLContext ssl = clientContext(clientAuth);
                HttpsURLConnection https = (HttpsURLConnection) connection;
                https.setSSLSocketFactory(ssl.getSocketFactory());
                https.setHostnameVerifier((host, session) -> true);
            }
            int status = connection.getResponseCode();
            if (connection.getErrorStream() != null) { connection.getErrorStream().close(); }
            return status;
        } finally { connection.disconnect(); }
    }

