    private ServerConnector connector(int index) throws Exception { return (ServerConnector) server().getConnectors()[index]; }

    private static void await(BooleanSupplier condition, int seconds) throws InterruptedException {
        long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(seconds);
        while (!condition.getAsBoolean()) {
            assertTrue(System.nanoTime() < deadline, "Timed out waiting for component state");
            Thread.sleep(25);
        }
    }

    @AfterEach
    void close() throws Exception {
        this.active = false;
        try {
            if (this.manager != null) {
                Object holder = TestUtil.getFieldValue(this.manager, "jettyServerHolder");
                Server running = holder == null ? null : (Server) TestUtil.getFieldValue(holder, "server");
                this.manager.getClass().getMethod("deactivate").invoke(this.manager);
                if (running != null) {
                    assertTrue(running.isStopped(), "Jetty must stop before temporary storage is removed");
                    for (var connector : running.getConnectors()) {
                        assertFalse(((ServerConnector) connector).isOpen(), "Listener must be closed");
                    }
                }
                assertTrue(((ExecutorService) TestUtil.getFieldValue(this.manager, "executorService")).isTerminated());
            }
        } finally {
            try {
                if (this.keystore != null) {
                    List<ExecutorService> executors = new ArrayList<>();
                    executors.add((ExecutorService) TestUtil.getFieldValue(this.keystore, "selfUpdaterExecutor"));
                    Optional<?> crl = (Optional<?>) TestUtil.getFieldValue(this.keystore, "crlManager");
                    if (crl.isPresent()) {
                        executors.add((ExecutorService) TestUtil.getFieldValue(crl.get(), "updateExecutor"));
                        executors.add((ExecutorService) TestUtil.getFieldValue(crl.get(), "downloadExecutor"));
                    }
                    this.keystore.deactivate();
                    for (ExecutorService executor : executors) { assertTrue(executor.awaitTermination(5, TimeUnit.SECONDS)); }
                }
            } finally {
                if (this.crlServer != null) { this.crlServer.close(); }
                if (this.loader != null) { this.loader.close(); }
                if (this.framework != null) {
                    this.framework.stop();
                    assertEquals(FrameworkEvent.STOPPED, this.framework.waitForStop(5000).getType());
                }
            }
        }
    }

    /** Only manager classes are isolated; FrameworkUtil resolves their actual private Equinox bundle context. */
    private static final class ManagerLoader extends URLClassLoader implements BundleReference {
        private final Bundle bundle;
        ManagerLoader(URL classes, Bundle bundle) {
            super(new URL[] { classes }, HttpServiceTest.class.getClassLoader());
            this.bundle = bundle;
        }
        @Override public Bundle getBundle() { return this.bundle; }
        @Override protected Class<?> loadClass(String name, boolean resolve) throws ClassNotFoundException {
            synchronized (getClassLoadingLock(name)) {
                Class<?> loaded = findLoadedClass(name);
                if (loaded == null) {
                    loaded = name.startsWith("org.eclipse.kura.http.server.manager.") ? findClass(name) : super.loadClass(name, false);
                }
                if (resolve) { resolveClass(loaded); }
                return loaded;
            }
        }
    }
